func TestOpDocs_Basic_Add(t *testing.T) {
	c := app.NewCalcTester(t)

	c.Eval("c 6 2 a")
	c.AssertStack("8")

	c.Eval("c 1.1 2.2 a")
	c.AssertStack("3.3")

	c.Eval("c 1/2 1/4 add")
	c.AssertStack("3/4")

	c.Eval("c 6+6i 2+2i a")
	c.AssertStack("8+8i")
}

